/*
 * This file contains JavaScript code to solve a dynamic programming problem.
 * It defines two primary functions, 'aaa' and 'bbb', which generate sequences
 * and populate DP tables based on these sequences.
 * The 'Main' function then processes input using these pre-calculated tables.
 */

// Global variables to store the generated sequences.
// 'rt' will hold the full sequence generated by 'aaa'.
// 'rtodd' will hold only the odd numbers from a similar sequence generated by 'bbb'.
var rt, rtodd;


/**
 * Function 'aaa' generates a specific sequence of numbers (likely related to triangular numbers)
 * and then populates a 2D dynamic programming array (dp1) based on this sequence.
 * This DP table helps in finding the minimum number of elements from the 'rt' sequence
 * that sum up to a target value.
 *
 * @param {number} n   The maximum target sum for which the DP table is built.
 * @param {Array<Array<number>>} dp1 A reference to the DP table (an array of arrays)
 *                                   that will be filled by this function.
 * @returns {number}   The total count of elements generated and stored in the 'rt' sequence.
 */
function aaa(n, dp1) {

    // Initialize auxiliary variables for sequence generation.
    // 'm' tracks the number of elements in 'rt'.
    // 'a', 'b', 'c' are internal counters/accumulators for sequence calculation.
    var m = 0, a = 1, b = 1, c = 1;

    // Initialize the global 'rt' array.
    rt = [];
    rt.push(0); // A zero is pushed as a placeholder or base element,
                // often used for 1-based indexing convenience in DP.

    // Loop to generate the sequence values.
    // The sequence seems to be 1, 2, 4, 7, 11, 16, ... (a_k = a_{k-1} + b_k, b_k = b_{k-1} + c_k, c_k = c_{k-1} + 1)
    while (a <= n) {
        m++;           // Increment the count of sequence elements.
        rt.push(a);    // Add the current 'a' value to the sequence.
        c++;           // Increment 'c'.
        b += c;        // Update 'b' by adding the new 'c'.
        a += b;        // Update 'a' by adding the new 'b'.
    }

    // --- DP Table Initialization for dp1 ---

    // Initialize the first row of the DP table.
    // dp1[0][j] represents the minimum elements to sum to 'j' using zero elements from the sequence.
    dp1[0] = [];
    dp1[0][0] = 0; // It takes 0 elements to sum to 0.

    // For any other sum 'j > 0', it's impossible with zero elements,
    // so we set it to a very large number (representing infinity).
    for (var i = 1; i <= n; i++) {
        dp1[0][i] = 1000000000; // A sufficiently large number.
    }

    // --- DP Table Population for dp1 ---

    // Iterate through each element of the generated 'rt' sequence (from index 1).
    for (var i = 1; i <= m; i++) {

        // Memory optimization: If 'i' is greater than 2, the row 'i-2' is no longer
        // needed for subsequent calculations, so it can be freed.
        if (i > 2) {
            dp1[i - 2] = null; // Set to null to allow garbage collection.
        }

        dp1[i] = []; // Initialize the current row 'i' of the DP table.

        // Iterate through all possible target sums 'j' from 0 to 'n'.
        for (var j = 0; j <= n; j++) {
            // Case 1: The current target sum 'j' is less than the current sequence element 'rt[i]'.
            // In this scenario, we cannot use 'rt[i]', so the minimum number of elements
            // is the same as calculated for the previous sequence element (row i-1).
            if (j < rt[i]) {
                dp1[i][j] = dp1[i - 1][j];
            }
            // Case 2: The current target sum 'j' is greater than or equal to 'rt[i]'.
            // We have two options:
            //   a) Don't use 'rt[i]': The count is dp1[i - 1][j].
            //   b) Use 'rt[i]': The count is dp1[i][j - rt[i]] + 1 (1 for using rt[i]).
            // We choose the minimum of these two options.
            else {
                dp1[i][j] = dp1[i - 1][j] < dp1[i][j - rt[i]] + 1
                    ? dp1[i - 1][j] // Option a: Don't use rt[i]
                    : dp1[i][j - rt[i]] + 1; // Option b: Use rt[i]
            }
        }
    }

    // Return the total number of elements in the 'rt' sequence.
    return m;
}


/**
 * Function 'bbb' is very similar to 'aaa', but with a key difference:
 * it only collects ODD numbers from its generated sequence into 'rtodd'.
 * It then populates a separate DP table (dp2) using only these odd sequence elements.
 *
 * @param {number} n   The maximum target sum for which the DP table is built.
 * @param {Array<Array<number>>} dp2 A reference to the DP table (an array of arrays)
 *                                   that will be filled by this function.
 * @returns {number}   The total count of ODD elements generated and stored in the 'rtodd' sequence.
 */
function bbb(n, dp2) {

    // Initialize auxiliary variables for sequence generation, identical to 'aaa'.
    var m = 0, a = 1, b = 1, c = 1;

    // Initialize the global 'rtodd' array.
    rtodd = [];
    rtodd.push(0); // A zero placeholder.

    // Loop to generate sequence values, but only push odd numbers to 'rtodd'.
    while (a <= n) {
        // Check if 'a' is an odd number.
        if (a % 2) {
            m++;         // Increment count only for odd numbers.
            rtodd.push(a); // Add the odd 'a' value to the sequence.
        }
        c++;           // Increment 'c'.
        b += c;        // Update 'b'.
        a += b;        // Update 'a'.
    }

    // --- DP Table Initialization for dp2 ---

    // Initialize the first row of the DP table.
    dp2[0] = [];
    dp2[0][0] = 0; // Base case: 0 elements for sum 0.

    // Fill the rest of the first row with a large number (infinity proxy).
    for (var i = 1; i <= n; i++) {
        dp2[0][i] = 1000000000; // Infinity.
    }

    // --- DP Table Population for dp2 ---

    // Iterate through each element of the generated 'rtodd' sequence.
    for (var i = 1; i <= m; i++) {
        // Memory optimization (Note: This condition `dp2[i] > 2` is likely a typo
        // and should probably be `i > 2` similar to function 'aaa'.
        // However, as per Type I cloning rules, it must be preserved exactly.)
        if (dp2[i] > 2) {
            dp2[i - 2] = null; // Attempt to free memory.
        }
        dp2[i] = []; // Initialize the current row 'i'.

        // Iterate through all possible target sums 'j'.
        for (var j = 0; j <= n; j++) {
            // Decision logic for DP table:
            // If 'j' is less than 'rtodd[i]', cannot use 'rtodd[i]'.
            if (j < rtodd[i]) {
                dp2[i][j] = dp2[i - 1][j];
            }
            // Otherwise, choose the minimum of not using 'rtodd[i]' or using it.
            else {
                dp2[i][j] = dp2[i - 1][j] < dp2[i][j - rtodd[i]] + 1
                    ? dp2[i - 1][j]
                    : dp2[i][j - rtodd[i]] + 1;
            }
        }
    }

    // Return the total number of elements in the 'rtodd' sequence.
    return m;
}

/**
 * The Main function serves as the entry point for processing the problem.
 * It reads input, calls 'aaa' and 'bbb' to prepare the DP tables,
 * and then uses these tables to answer queries from the input.
 *
 * @param {string} input The entire input content as a single string,
 *                       expected to have newline-separated numbers.
 */
function Main(input) {
    // Split the input string into an array of individual lines.
    input = input.split("\n");

    // Declare two empty arrays that will be used as DP tables.
    var dp1 = [], dp2 = [];

    // Call 'aaa' and 'bbb' to populate the DP tables.
    // The maximum target sum 'n' is hardcoded to 1,000,000 for both.
    // m1 and m2 will store the counts of elements in their respective sequences.
    var m1 = aaa(1000000, dp1);
    var m2 = bbb(1000000, dp2);

    // Loop through the input queries.
    // The loop condition '1' makes it an infinite loop,
    // which is expected to be broken by an explicit 'break' statement.
    for (var i = 0; 1; i++) {
        // Parse the current line of input as an integer (base 10).
        var n = parseInt(input[i], 10);

        // Check for the termination condition: if 'n' is 0, exit the loop.
        if (n == 0) {
            break;
        }

        // Retrieve the pre-calculated results from the DP tables.
        // 'a' is the result using the full sequence (from dp1).
        // 'b' is the result using only the odd sequence (from dp2).
        var a = dp1[m1][n];
        var b = dp2[m2][n];

        // Print the two results, separated by a space, to standard output.
        console.log(a, b);
    }

}


// Execute the Main function by reading input from standard input.
// This assumes a Node.js environment where 'require("fs")' is available
// and '/dev/stdin' is the path for standard input.
Main(require("fs").readFileSync("/dev/stdin", "utf8"));